"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[161],{94123:e=>{e.exports=JSON.parse('{"functions":[{"name":"string","desc":"Creates a schema that accepts any string.","params":[],"returns":[{"desc":"","lua_type":"StringSchema"}],"function_type":"static","tags":["Constructor"],"source":{"line":1245,"path":"src/init.luau"}},{"name":"number","desc":"Creates a schema that accepts any number except NaN.","params":[],"returns":[{"desc":"","lua_type":"NumberSchema"}],"function_type":"static","tags":["Constructor"],"source":{"line":1256,"path":"src/init.luau"}},{"name":"boolean","desc":"Creates a schema that accepts `true` or `false`.","params":[],"returns":[{"desc":"","lua_type":"BooleanSchema"}],"function_type":"static","tags":["Constructor"],"source":{"line":1267,"path":"src/init.luau"}},{"name":"uuid","desc":"Creates a schema that accepts a UUID: 8-4-4-4-12 hexadecimal digits, in\\neither case, carrying a version of 1 to 8 and an RFC 9562 variant.\\n\\n```lua\\nlocal Id = v.uuid()\\nlocal SessionId = v.uuid({ version = \\"v7\\" })\\n\\nId:parse(\\"01912d68-783e-7cc0-a2f0-5f8b1d3e9a7c\\") --\x3e ok\\nSessionId:parse(\\"6f9619ff-8b86-4d11-b42d-00cf4fc964ff\\")\\n--\x3e errors: expected a v7 uuid, got v4\\n```\\n\\nBecause the version and variant are checked, the nil UUID and the max UUID\\nare both rejected. Use [Vet.guid] when you only care about the layout.\\n\\nThe result is a plain [StringSchema], so `:optional()`, `:default()` and\\n`Vet.infer` behave exactly as they do for any other string.","params":[{"name":"options","desc":"Pass `{ version = \\"v4\\" }` to pin the version","lua_type":"UuidOptions?"}],"returns":[{"desc":"","lua_type":"StringSchema"}],"function_type":"static","tags":["Constructor"],"errors":[{"lua_type":"\\"unknown uuid version ...\\"","desc":"Thrown when `options.version` is not v4 to v8"}],"source":{"line":1296,"path":"src/init.luau"}},{"name":"guid","desc":"Creates a schema that accepts a GUID: the same 8-4-4-4-12 layout as\\n[Vet.uuid], optionally wrapped in braces, with no variant requirement.\\n\\n```lua\\nlocal Id = v.guid()\\n\\nId:parse(\\"{6F9619FF-8B86-D011-B42D-00CF4FC964FF}\\") --\x3e ok\\nId:parse(\\"6f9619ff-8b86-d011-b42d-00cf4fc964ff\\")   --\x3e ok\\n```\\n\\nThis is the shape `HttpService:GenerateGUID` returns, which is braced and\\nuppercase by default. Values Microsoft produced do not always follow the\\nRFC variant rule, so only the layout is enforced unless you pass a version.","params":[{"name":"options","desc":"Pass `{ version = \\"v4\\" }` to pin the version","lua_type":"UuidOptions?"}],"returns":[{"desc":"","lua_type":"StringSchema"}],"function_type":"static","tags":["Constructor"],"errors":[{"lua_type":"\\"unknown guid version ...\\"","desc":"Thrown when `options.version` is not v4 to v8"}],"source":{"line":1321,"path":"src/init.luau"}},{"name":"array","desc":"Creates a schema that accepts an array of `item`.\\n\\n```lua\\nlocal Scores = v.array(v.number():integer())\\n\\nScores:parse({ 1, 2, 3 }) --\x3e { 1, 2, 3 }\\nScores:parse({ 1, 1.5 })  --\x3e errors: [2]: expected an integer, got 1.5\\n```","params":[{"name":"item","desc":"Schema every element must satisfy","lua_type":"S"}],"returns":[{"desc":"","lua_type":"ArraySchema<Vet.infer<S>>"}],"function_type":"static","tags":["Constructor"],"source":{"line":1340,"path":"src/init.luau"}},{"name":"object","desc":"Creates a schema that validates a table field by field. The field types come\\nfrom the shape, so the schema is the only place they are declared.\\n\\n```lua\\nlocal User = v.object({\\n\\tname = v.string():min(3),\\n\\tnickname = v.string():optional(),\\n})\\n\\ntype User = v.infer<typeof(User)> --\x3e { name: string, nickname: string? }\\n```","params":[{"name":"shape","desc":"Table mapping field names to schemas","lua_type":"S"}],"returns":[{"desc":"","lua_type":"ObjectSchema<Vet.objectOutput<S>>"}],"function_type":"static","tags":["Constructor"],"source":{"line":1366,"path":"src/init.luau"}}],"properties":[],"types":[{"name":"Issue","desc":"","fields":[{"name":"path","lua_type":"{ string | number }","desc":"Location of the failure inside the value"},{"name":"message","lua_type":"string","desc":"Human-readable description of the failure"}],"source":{"line":24,"path":"src/init.luau"}},{"name":"Result<T>","desc":"Returned by `safeParse`. Narrow it with `if result.success then` to get a\\ntyped `result.value`.","lua_type":"{ success: true, value: T } | { success: false, issues: { Issue } }","source":{"line":36,"path":"src/init.luau"}},{"name":"infer<S>","desc":"Extracts the type a schema parses to, so a schema can be the single source\\nof truth for both validation and types.\\n\\n```lua\\nlocal Username = v.string():min(3)\\ntype Username = v.infer<typeof(Username)> --\x3e string\\n\\nlocal Nickname = v.string():optional()\\ntype Nickname = v.infer<typeof(Nickname)> --\x3e string?\\n```\\n\\nGiven a union of schemas, the result is the union of what each one parses\\nto: `Vet.infer<StringSchema | NumberSchema>` is `string | number`.\\n\\nThis is a user-defined type function, so it runs during analysis and costs\\nnothing at runtime. It requires a Luau version that supports user-defined\\ntype functions.","lua_type":"the value type produced by schema S","source":{"line":60,"path":"src/init.luau"}},{"name":"objectOutput<S>","desc":"Maps `{ name: StringSchema, age: NumberSchema }` to `{ name: string, age:\\nnumber }`. Used to type the result of `Vet.object`, so the shape you pass in\\nis the only place the field types are written down.\\n\\nThe property walk duplicates the one in [Vet.infer] because a type function\\ncannot call another type function.","lua_type":"the record type a shape of schemas parses to","source":{"line":133,"path":"src/init.luau"}},{"name":"UuidVersion","desc":"Versions accepted by [Vet.uuid] and [Vet.guid]. Version 4 is random, 5 is\\nname-based, 6 is reordered time, 7 is Unix epoch time, and 8 is custom.","lua_type":"\\"v4\\" | \\"v5\\" | \\"v6\\" | \\"v7\\" | \\"v8\\"","source":{"line":1144,"path":"src/init.luau"}},{"name":"UuidOptions","desc":"","fields":[{"name":"version","lua_type":"UuidVersion?","desc":"Version the identifier must declare"}],"source":{"line":1151,"path":"src/init.luau"}}],"name":"Vet","desc":"Lua-first schema validation with type inference.\\n\\n```lua\\nlocal v = require(ReplicatedStorage.Packages.Vet)\\n\\nlocal Name = v.string():min(3):max(22)\\n\\nName:parse(\\"kyle\\") --\x3e \\"kyle\\"\\nName:parse(\\"ky\\")   --\x3e errors\\n```","source":{"line":17,"path":"src/init.luau"}}')}}]);